    .filter((d) => d.isDirectory() && d.name.startsWith("run-"))
    .map((d) => d.name)
    .sort();
  if (dirs.length === 0) throw new Error("No runs found under results/. Run `npm run run` first.");
  return dirs[dirs.length - 1];
